    for (int j = 1; j <= m; j++) {
        cur[0] = -1;
        for (int i = 1; i <= n; i++) {
            int v = cur[i - 1];
            if (s[i - 1] == t[j - 1] && prev[i - 1] > v) v = prev[i - 1];
            cur[i] = v;
        }
        swap(prev, cur);
    }
    int answer = -1;
    for (int i = 1; i <= n; i++) {
        if (prev[i] >= 0 && (answer < 0 || i - prev[i] < answer)) answer = i - prev[i];
